```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An ontology of tradable securities, derivatives, investment funds and related financial-accounting concepts, modelled from a corpus on securities, bonds, stocks, derivatives, funds, and IAS32/IFRS9 definitions." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties, which can be created, traded, modified and settled; gives rise to a financial asset of one entity and a financial liability or equity instrument of another (IAS 32)." .

fis:Underlier a owl:Class ;
  rdfs:label "underlier" , "underlying asset" ;
  rdfs:comment "An item (asset, rate, index, currency or event) that can or must be bought or sold, or by reference to which a derivative's value is determined." .

fis:FinancialInstrument rdfs:subClassOf fis:Underlier .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlier ;
  rdfs:comment "A physical or fungible good, e.g. corn or oil, that can serve as the underlier of a derivative." .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:Underlier ;
  rdfs:comment "A published index of prices (e.g. a stock market index) usable as a derivative underlier." .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:InterestRateBenchmark a owl:Class ; rdfs:subClassOf fis:Underlier ;
  rdfs:comment "A reference interest rate such as LIBOR, EURIBOR or SOFR." .
fis:CreditEvent a owl:Class ; rdfs:subClassOf fis:Underlier ;
  rdfs:comment "A specific event, such as default, on which a derivative's payoff is contingent." .

fis:FinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "financial asset" ;
  rdfs:comment "Any asset that is cash, an equity instrument of another entity, a contractual right to receive cash or another financial instrument, or a contractual right to exchange financial instruments under potentially favourable conditions (IAS 32)." .

fis:FinancialLiability a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "financial liability" ;
  rdfs:comment "A contractual obligation to deliver cash or another financial asset to another entity, or to exchange financial instruments under potentially unfavourable conditions (IAS 32)." .

fis:EquityInstrument a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "equity instrument" ;
  rdfs:comment "Any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities (IAS 32)." .

fis:CashInstrument a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "cash instrument" ;
  rdfs:comment "An instrument whose value is determined directly by the markets, such as securities, loans and deposits." .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument .
fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .

fis:Derivative a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "derivative" , "derivative instrument" ;
  rdfs:comment "A financial contract whose value is derived from the performance of an underlier (asset, index, rate or event). Note: BIS classifies derivatives into three basic types (forwards, swaps, options), treating futures as standardised forwards, whereas most other sources treat forwards, futures, options and swaps as four distinct variants; this ontology follows the more common four-way taxonomy." .

fis:Derivative owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:FinancialInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Underlier ]
  )
] .

fis:CompoundFinancialInstrument a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "compound financial instrument" ;
  rdfs:comment "Under IAS 32, an instrument such as a convertible bond must be split into a financial-liability component and an equity component at issuance; this differs from the common market view of a convertible as a single debt security with an embedded option." .

fis:CompoundFinancialInstrument owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:FinancialInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasLiabilityComponent ; owl:someValuesFrom fis:FinancialLiability ]
    [ a owl:Restriction ; owl:onProperty fis:hasEquityComponent ; owl:someValuesFrom fis:EquityInstrument ]
  )
] .

#################################################################
# SECURITY AND THE DEBT / EQUITY / HYBRID CLAIM TAXONOMY
#################################################################

fis:Security a owl:Class ; rdfs:subClassOf fis:CashInstrument, fis:FinancialAsset ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset representing a claim on an issuer. Note: the UK FCA Handbook defines 'security' narrowly (equities, debentures, government/public securities, warrants, units, etc., excluding most derivatives), while in the US a 'security' broadly includes debt, equity and derivatives. This ontology follows the majority view that Security = debt/equity/hybrid instruments, keeping Derivative as a sibling top-level class, and records the US-law conflict here." .

fis:Security owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:FinancialAsset
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Issuer ]
  )
] .

fis:Claim a owl:Class ; rdfs:comment "The nature of the holder's claim on the issuer under a security." .
fis:ResidualClaim a owl:Class ; rdfs:subClassOf fis:Claim ;
  rdfs:comment "A claim to the residual value of the issuer after creditors are paid, with upside participation (ownership)." .
fis:FixedClaim a owl:Class ; rdfs:subClassOf fis:Claim ;
  rdfs:comment "A claim to fixed, contractually defined payments of principal and interest (creditor relationship)." .
[] a owl:AllDisjointClasses ; owl:members ( fis:ResidualClaim fis:FixedClaim ) .

fis:EquitySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "equity security" , "stock" , "share" ;
  rdfs:comment "A share of equity interest in an entity; holder is a shareholder with a residual claim and generally voting rights." .
fis:EquitySecurity owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasClaimType ; owl:someValuesFrom fis:ResidualClaim ]
  )
] .

fis:DebtSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "debt security" , "fixed income security" ;
  rdfs:comment "Evidence of a debt under which the holder is entitled to payment of principal and interest; generally issued for a fixed term." .
fis:DebtSecurity owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasClaimType ; owl:someValuesFrom fis:FixedClaim ]
  )
] .

[] a owl:AllDisjointClasses ; owl:members ( fis:EquitySecurity fis:DebtSecurity ) .

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "hybrid security" ;
  rdfs:comment "A security that combines some characteristics of both debt and equity securities, e.g. preference shares, convertibles, equity warrants." .
fis:HybridSecurity owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasClaimType ; owl:someValuesFrom fis:ResidualClaim ]
    [ a owl:Restriction ; owl:onProperty fis:hasClaimType ; owl:someValuesFrom fis:FixedClaim ]
  )
] .

#################################################################
# ISSUERS AND HOLDERS
#################################################################

fis:Issuer a owl:Class ; rdfs:label "issuer" ;
  rdfs:comment "The entity obligated on a security or other financial instrument." .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:comment "E.g. the World Bank, IMF, African/Asian Development Banks." .
fis:MunicipalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
  rdfs:label "local authority" ;
  rdfs:comment "State, provincial, territorial or municipal governmental unit other than a sovereign government." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Issuer .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:SovereignGovernment fis:SupranationalOrganization fis:MunicipalGovernment fis:Corporation fis:Bank ) .

fis:Holder a owl:Class ; rdfs:label "holder" , "investor" ;
  rdfs:comment "A party entitled to rights under a security by virtue of holding or being registered as owner of it." .
fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Holder ;
  rdfs:comment "A holder of one or more shares of equity security; also called stockholder." .
fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Holder .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Holder ;
  rdfs:comment "A member of the public investing personally, other than by way of business." .
fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Holder ;
  rdfs:comment "An investment bank, insurance company, pension fund or other managed fund acting on its own account or on behalf of clients." .
[] a owl:AllDisjointClasses ; owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) .

fis:Underwriter a owl:Class ; rdfs:comment "A securities firm or bank that buys an entire bond or share issue from the issuer and resells it to investors." .
fis:Bookrunner a owl:Class ; rdfs:subClassOf fis:Underwriter ;
  rdfs:comment "The underwriter that arranges a bond issue and has direct contact with investors; listed first in the tombstone ad." .
fis:CreditRatingAgency a owl:Class ; rdfs:comment "An agency, such as Standard & Poor's or Moody's, that assigns credit ratings to bonds and issuers." .

#################################################################
# CLASSIFICATION DIMENSIONS (VALUE CLASSES) FOR DEBT SECURITIES
#################################################################

fis:CouponType a owl:Class .
fis:FixedCoupon a owl:Class ; rdfs:subClassOf fis:CouponType .
fis:FloatingCoupon a owl:Class ; rdfs:subClassOf fis:CouponType .
fis:ZeroCoupon a owl:Class ; rdfs:subClassOf fis:CouponType .
[] a owl:AllDisjointClasses ; owl:members ( fis:FixedCoupon fis:FloatingCoupon fis:ZeroCoupon ) .

fis:TermCategory a owl:Class .
fis:ShortTerm a owl:Class ; rdfs:subClassOf fis:TermCategory ; rdfs:comment "Maturity under one year (e.g. Treasury bills)." .
fis:MediumTerm a owl:Class ; rdfs:subClassOf fis:TermCategory ; rdfs:comment "Maturity between one and ten years (e.g. Treasury notes)." .
fis:LongTerm a owl:Class ; rdfs:subClassOf fis:TermCategory ; rdfs:comment "Maturity between ten and thirty years (e.g. Treasury bonds)." .
fis:PerpetualTerm a owl:Class ; rdfs:subClassOf fis:TermCategory ; rdfs:comment "No maturity period." .
[] a owl:AllDisjointClasses ; owl:members ( fis:ShortTerm fis:MediumTerm fis:LongTerm fis:PerpetualTerm ) .

fis:CreditRatingCategory a owl:Class .
fis:InvestmentGradeRating a owl:Class ; rdfs:subClassOf fis:CreditRatingCategory ;
  rdfs:comment "Ratings of AAA, AA, A or BBB." .
fis:HighYieldRating a owl:Class ; rdfs:subClassOf fis:CreditRatingCategory ;
  rdfs:label "junk rating" ;
  rdfs:comment "Ratings of BB and below." .
[] a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeRating fis:HighYieldRating ) .

fis:RegistrationForm a owl:Class .
fis:BearerForm a owl:Class ; rdfs:subClassOf fis:RegistrationForm ;
  rdfs:comment "Holder's rights attach merely by possession of the certificate." .
fis:RegisteredForm a owl:Class ; rdfs:subClassOf fis:RegistrationForm ;
  rdfs:comment "Holder's rights depend on appearance on a security register." .
fis:BookEntryForm a owl:Class ; rdfs:subClassOf fis:RegistrationForm ;
  rdfs:comment "Non-certificated, electronic/dematerialized form." .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerForm fis:RegisteredForm fis:BookEntryForm ) .

fis:SeniorityType a owl:Class .
fis:SeniorSeniority a owl:Class ; rdfs:subClassOf fis:SeniorityType .
fis:SubordinatedSeniority a owl:Class ; rdfs:subClassOf fis:SeniorityType .
[] a owl:AllDisjointClasses ; owl:members ( fis:SeniorSeniority fis:SubordinatedSeniority ) .

fis:OptionFeature a owl:Class ; rdfs:comment "An embedded option granting the issuer or holder an early-redemption right." .
fis:CallFeature a owl:Class ; rdfs:subClassOf fis:OptionFeature ;
  rdfs:comment "Gives the issuer the right to repay the bond before maturity." .
fis:PutFeature a owl:Class ; rdfs:subClassOf fis:OptionFeature ;
  rdfs:comment "Gives the holder the right to force early repayment." .

fis:RepaymentSource a owl:Class .
fis:TaxingPowerSource a owl:Class ; rdfs:subClassOf fis:RepaymentSource ;
  rdfs:comment "Backing by the issuer's unlimited or limited taxing power." .
fis:RevenueSource a owl:Class ; rdfs:subClassOf fis:RepaymentSource ;
  rdfs:comment "Repayment solely from revenues of a specified revenue-generating project." .
fis:PropertyAssessmentSource a owl:Class ; rdfs:subClassOf fis:RepaymentSource ;
  rdfs:comment "Repayment based on property tax assessments." .

#################################################################
# BOND AND ITS SUBCLASSES
#################################################################

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "A security under which the issuer owes the holder a debt, obliged to repay principal at maturity and usually to pay periodic interest (coupon)." .

fis:Debenture a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "An unsecured debt security with a long maturity (typically at least ten years); note the US sense ('unsecured bond') differs from the UK sense emphasising long maturity." .
fis:Note a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "A debt security with a shorter maturity than a debenture." .

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "money market instrument" ;
  rdfs:comment "A short-term debt instrument with an original maturity of one year or less." .
fis:MoneyMarketInstrument owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:DebtSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasTermCategory ; owl:someValuesFrom fis:ShortTerm ]
  )
] .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "An unsecured promissory note with a fixed maturity usually under 270 days." .
fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions with a specific fixed term." .
fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument, fis:Bond ;
  rdfs:comment "A zero-coupon government debt obligation maturing in three to twelve months." .
fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:MunicipalNote a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term borrowing by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .
fis:EurocommercialPaper a owl:Class ; rdfs:subClassOf fis:CommercialPaper .

fis:EuroDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "A security issued internationally outside its domestic market in a denomination different from the issuer's domicile." .
fis:Eurobond a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity, fis:Bond ;
  rdfs:comment "Underwritten, unsecured, with interest paid gross." .
fis:Euronote a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity .

#--- issuer-based bond classification (disjoint) ---------------

fis:GovernmentBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "treasury bond" , "sovereign bond" ;
  rdfs:comment "A medium or long term debt security issued by a sovereign government or its agencies." .
fis:GovernmentBond owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
  )
] .

fis:SupranationalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "supra" ;
  rdfs:comment "A bond issued by a supranational organisation such as the World Bank." .
fis:SupranationalBond owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ]
  )
] .

fis:MunicipalBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "muni" ;
  rdfs:comment "A bond issued by a local authority or sub-sovereign governmental unit; known in the US as a municipal bond." .
fis:MunicipalBond owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:MunicipalGovernment ]
  )
] .

fis:CorporateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A bond issued by a corporation to raise financing for operations, M&A or expansion." .
fis:CorporateBond owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
  )
] .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:GovernmentBond fis:SupranationalBond fis:MunicipalBond fis:CorporateBond ) .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Principal and interest secured by the full faith and credit of the issuer and its taxing power." .
fis:GeneralObligationBond owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:MunicipalBond
    [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:TaxingPowerSource ]
  )
] .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repayment guaranteed solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .
fis:RevenueBond owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:MunicipalBond
    [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:RevenueSource ]
  )
] .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repayment based on property tax assessments of properties within the issuer's boundaries." .
fis:AssessmentBond owl:equivalentClass [
  a owl:Class ;
  owl:intersectionOf ( fis:MunicipalBond
    [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:PropertyAssessmentSource ]
  )
] .

fis:Gilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ; rdfs:comment "A UK government bond." .
fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US Treasury security with maturity of two to ten years." .
fis:TreasuryNote owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:GovernmentBond
    [ a owl:Restriction ; owl:onProperty fis:hasTermCategory ; owl:someValuesFrom fis:MediumTerm ] )
] .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US Treasury security with the longest maturity, 20 to 30 years." .
fis:TreasuryBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:GovernmentBond
    [ a owl:Restriction ; owl:onProperty fis:hasTermCategory ; owl:someValuesFrom fis:LongTerm ] )
] .
fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:label "TIPS" ; rdfs:comment "An inflation-indexed government bond whose principal is adjusted to the CPI." .

#--- coupon-based bond classification (disjoint) ----------------

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .
fis:FixedRateBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:FixedCoupon ] )
] .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "floater" ;
  rdfs:comment "Coupon varies, linked to a reference rate such as LIBOR, EURIBOR or SOFR." .
fis:FloatingRateNote owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:FloatingCoupon ] )
] .
fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "discount bond" , "deep discount bond" ;
  rdfs:comment "Pays no periodic interest; issued at a substantial discount, full principal paid at maturity." .
fis:ZeroCouponBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:ZeroCoupon ] )
] .
[] a owl:AllDisjointClasses ; owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) .

fis:StripBond a owl:Class ; rdfs:subClassOf fis:ZeroCouponBond ;
  rdfs:comment "A zero-coupon bond created by separating ('stripping') the coupons from the principal of a coupon bond." .

#--- maturity / perpetuity ---------------------------------------

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "perpetuity" , "irredeemable bond" ;
  rdfs:comment "A bond with no maturity date." .
fis:PerpetualBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasTermCategory ; owl:someValuesFrom fis:PerpetualTerm ] )
] .

#--- credit rating classification (disjoint) ---------------------

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "high grade bond" .
fis:InvestmentGradeBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:someValuesFrom fis:InvestmentGradeRating ] )
] .
fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "junk bond" , "non-investment grade bond" .
fis:HighYieldBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:someValuesFrom fis:HighYieldRating ] )
] .
[] a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) .

#--- embedded option classification -------------------------------

fis:CallableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Gives the issuer the right to repay the bond before maturity on call dates." .
fis:CallableBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallFeature ] )
] .
fis:PutableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "retractable bond" ;
  rdfs:comment "Gives the holder the right to force the issuer to repay the bond before maturity." .
fis:PutableBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutFeature ] )
] .
fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

#--- registration form (disjoint) ---------------------------------

fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:BearerBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:someValuesFrom fis:BearerForm ] )
] .
fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:RegisteredBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:someValuesFrom fis:RegisteredForm ] )
] .
fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:BookEntryBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasRegistrationForm ; owl:someValuesFrom fis:BookEntryForm ] )
] .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerBond fis:RegisteredBond fis:BookEntryBond ) .

#--- seniority (disjoint) ------------------------------------------

fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:SeniorBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:someValuesFrom fis:SeniorSeniority ] )
] .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:SubordinatedBond owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:someValuesFrom fis:SubordinatedSeniority ] )
] .
[] a owl:AllDisjointClasses ; owl:members ( fis:SeniorBond fis:SubordinatedBond ) .

#--- other named bonds (subclass + comment) ------------------------

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "Issued by a government to fund military operations during wartime." .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Raises finance for climate change mitigation or adaptation projects." .
fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets that remain on the issuer's balance sheet." .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Public-sector entities repay private investors after verified improved social outcomes." .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:FixedRateBond ;
  rdfs:comment "The issuer redeems randomly selected individual bonds, some above face value." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .
fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "linker" , "index-linked bond" ;
  rdfs:comment "Principal and interest payments are indexed to a price level such as the CPI." .
fis:ForeignCurrencyBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued in a currency other than the issuer's domestic currency, e.g. a samurai bond." .

#################################################################
# ASSET-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "ABS" ;
  rdfs:comment "An umbrella term for a security backed by a pool of assets. Note: the term is sometimes used narrowly to mean only securities backed by consumer loans (excluding MBS and CDO), conflicting with the broader umbrella usage; this ontology follows the broader umbrella usage and models MBS/CDO as subclasses." .

fis:MortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:label "MBS" ;
  rdfs:comment "An asset-backed security secured by a mortgage or pool of mortgages." .
fis:CollateralizedDebtObligation a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  rdfs:label "CDO" ;
  rdfs:comment "A structured asset-backed security issued in tranches backed by a pool of bonds or other debt obligations." .
fis:HomeEquityLoanBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity .
fis:AutoLoanBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity .
fis:CreditCardBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity .
fis:StudentLoanBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ; rdfs:label "SLABS" .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "RMBS" ; rdfs:comment "Secured by single-family, one- to four-unit residential real estate." .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "CMBS" ; rdfs:comment "Secured by commercial and multi-family properties." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "CMO" , "pay-through bond" .
fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Interest and principal payments pass through the trust to holders pro rata." .
fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "SMBS" .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "IO" .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "PO" .
fis:NetInterestMarginSecurity a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ; rdfs:label "NIMS" .
[] a owl:AllDisjointClasses ; owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip fis:NetInterestMarginSecurity ) .

#################################################################
# EQUITY SECURITIES
#################################################################

fis:VotingRightsType a owl:Class .
fis:VotingShare a owl:Class ; rdfs:subClassOf fis:VotingRightsType .
fis:NonVotingShare a owl:Class ; rdfs:subClassOf fis:VotingRightsType .
[] a owl:AllDisjointClasses ; owl:members ( fis:VotingShare fis:NonVotingShare ) .

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "ordinary share" , "voting share" , "equity share" ;
  rdfs:comment "Carries voting rights on corporate decisions and the board; lowest priority on dividends and liquidation proceeds." .
fis:CommonStock owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:EquitySecurity
    [ a owl:Restriction ; owl:onProperty fis:hasVotingRightsType ; owl:someValuesFrom fis:VotingShare ] )
] .

fis:DividendAccumulationType a owl:Class .
fis:CumulativeAccumulation a owl:Class ; rdfs:subClassOf fis:DividendAccumulationType .
fis:NoncumulativeAccumulation a owl:Class ; rdfs:subClassOf fis:DividendAccumulationType .
[] a owl:AllDisjointClasses ; owl:members ( fis:CumulativeAccumulation fis:NoncumulativeAccumulation ) .

fis:PreferredStock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "preferred share" , "preference share" , "preferred" ;
  rdfs:comment "Senior to common stock, usually without voting rights, with priority in dividends and liquidation; generally considered a hybrid instrument, though legally a form of capital stock (equity). Note: under IAS 32, a mandatorily redeemable preference share is classified as a financial liability rather than equity, conflicting with the general market treatment of preferred stock as equity capital." .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock .
fis:CumulativePreferredStock owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulationType ; owl:someValuesFrom fis:CumulativeAccumulation ] )
] .
fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ; rdfs:label "straight preferred stock" .
fis:NoncumulativePreferredStock owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulationType ; owl:someValuesFrom fis:NoncumulativeAccumulation ] )
] .
[] a owl:AllDisjointClasses ; owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) .

fis:CallablePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Issuer may repurchase the share at its discretion (US preferred shares normally carry a call provision)." .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "DR" ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, trading on a local exchange." .
fis:DepositaryReceipt owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ]
  )
] .
fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "ADR" .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "EDR" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "GDR" .
[] a owl:AllDisjointClasses ;
   owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

#################################################################
# CONVERTIBLE / HYBRID SECURITIES AND WARRANTS
#################################################################

fis:ConvertibleSecurity a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "A bond or preferred stock that the holder may convert, at election, into the ordinary shares of the issuer (or, for exchangeables, another corporation)." .
fis:ConvertibleSecurity owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:HybridSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] )
] .

fis:ConvertibleBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:ConvertibleSecurity, fis:CompoundFinancialInstrument ;
  rdfs:label "convertible note" , "convertible debenture" ;
  rdfs:comment "A bond convertible into the issuer's common stock; typically yields less than comparable non-convertible debt." .
fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Exchangeable into shares of a corporation other than the issuer." .
fis:ConvertiblePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock, fis:ConvertibleSecurity, fis:CompoundFinancialInstrument ;
  rdfs:comment "Preferred stock convertible into a fixed number of common shares." .
fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:MandatoryConvertibleBond ;
  rdfs:label "CoCo" ;
  rdfs:comment "Automatically converts into equity if a pre-specified trigger event occurs." .
fis:PackagedConvertible a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "A straight bond and a call option/warrant wrapped together, each separately tradeable." .
fis:SyntheticConvertible a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Issued by an investment bank to replicate a convertible payoff on a specific underlying equity, settled in cash." .

fis:EquityWarrant a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "warrant" ;
  rdfs:comment "An option issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time; often issued with bonds or existing equities, sometimes detachable." .

#################################################################
# DERIVATIVE SUBCLASSES: LOCK PRODUCTS AND OPTION PRODUCTS
#################################################################

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .
fis:OptionProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under the terms specified." .
[] a owl:AllDisjointClasses ; owl:members ( fis:LockProduct fis:OptionProduct ) .

fis:TradingVenue a owl:Class .
fis:ExchangeTradedVenue a owl:Class ; rdfs:subClassOf fis:TradingVenue .
fis:OverTheCounterVenue a owl:Class ; rdfs:subClassOf fis:TradingVenue .
[] a owl:AllDisjointClasses ; owl:members ( fis:ExchangeTradedVenue fis:OverTheCounterVenue ) .

fis:ExchangeTradedDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ; rdfs:label "ETD" .
fis:ExchangeTradedDerivative owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Derivative
    [ a owl:Restriction ; owl:onProperty fis:hasTradingVenue ; owl:someValuesFrom fis:ExchangeTradedVenue ] )
] .
fis:OverTheCounterDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ; rdfs:label "OTC derivative" .
fis:OverTheCounterDerivative owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Derivative
    [ a owl:Restriction ; owl:onProperty fis:hasTradingVenue ; owl:someValuesFrom fis:OverTheCounterVenue ] )
] .
[] a owl:AllDisjointClasses ; owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) .

fis:Forward a owl:Class ; rdfs:subClassOf fis:LockProduct, fis:OverTheCounterDerivative ;
  rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today; not exchange-traded." .
fis:Future a owl:Class ; rdfs:subClassOf fis:LockProduct, fis:ExchangeTradedDerivative ;
  rdfs:label "futures contract" ;
  rdfs:comment "A standardized contract, written by a clearing house operating an exchange, to buy or sell an asset at a price agreed today, for delivery at a specified future date." .

fis:Swap a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  rdfs:comment "Two counterparties exchange cash flows ('legs') of one financial instrument for those of another, over a notional principal amount that is not itself exchanged." .
fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:Swap ;
  rdfs:label "CDS" , "credit swap" ;
  rdfs:comment "Seller compensates the buyer if a reference loan or entity suffers a credit event (e.g. default); buyer pays periodic fee/spread." .
[] a owl:AllDisjointClasses ;
   owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CommoditySwap fis:EquitySwap fis:CreditDefaultSwap ) .

fis:RightType a owl:Class .
fis:BuyRight a owl:Class ; rdfs:subClassOf fis:RightType .
fis:SellRight a owl:Class ; rdfs:subClassOf fis:RightType .
[] a owl:AllDisjointClasses ; owl:members ( fis:BuyRight fis:SellRight ) .

fis:ExerciseStyle a owl:Class .
fis:AmericanStyle a owl:Class ; rdfs:subClassOf fis:ExerciseStyle ; rdfs:comment "May be exercised any time on or before expiration." .
fis:EuropeanStyle a owl:Class ; rdfs:subClassOf fis:ExerciseStyle ; rdfs:comment "May only be exercised on expiry." .
fis:BermudanStyle a owl:Class ; rdfs:subClassOf fis:ExerciseStyle ; rdfs:comment "May be exercised only on specified dates on or before expiration." .
[] a owl:AllDisjointClasses ; owl:members ( fis:AmericanStyle fis:EuropeanStyle fis:BermudanStyle ) .

fis:Option a owl:Class ; rdfs:subClassOf fis:OptionProduct ;
  rdfs:comment "A contract giving the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:CallOption owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasRightType ; owl:someValuesFrom fis:BuyRight ] )
] .
fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:PutOption owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasRightType ; owl:someValuesFrom fis:SellRight ] )
] .
[] a owl:AllDisjointClasses ; owl:members ( fis:CallOption fis:PutOption ) .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:AmericanOption owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:AmericanStyle ] )
] .
fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:EuropeanOption owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:EuropeanStyle ] )
] .
fis:BermudanOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:BermudanOption owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:BermudanStyle ] )
] .
[] a owl:AllDisjointClasses ; owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over a preset period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The underlying price must pass a barrier level before the option can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "An all-or-nothing option paying the full amount if a condition is met at expiration." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Any of a broad category of options with complex financial structures." .
fis:EmployeeStockOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "An option awarded by a company to employees as incentive compensation; usually not transferable." .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:OptionProduct, fis:EquityWarrant ;
  rdfs:comment "A long-dated option, generally traded over the counter." .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "fund" ;
  rdfs:comment "An investment vehicle that pools money from many investors to purchase a portfolio of other securities; the fund's own value is derived from the underlying securities it holds." .
fis:InvestmentFund owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Security ] )
] .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "An SEC-registered open-end investment company; shares transact at the fund's next calculated net asset value." .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "ETF" ;
  rdfs:comment "Shares trade on national securities exchanges at market prices that may differ from net asset value." .
fis:ExchangeTradedFund owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
    [ a owl:Restriction ; owl:onProperty fis:hasTradingVenue ; owl:someValuesFrom fis:ExchangeTradedVenue ] )
] .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools investor money with fewer regulatory protections; typically available only to high-net-worth individuals." .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
fis:MoneyMarketFund owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:MoneyMarketInstrument ] )
] .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "income fund" .
fis:BondFund owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ] )
] .
fis:EquityFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "stock fund" .
fis:EquityFund owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] )
] .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Passively managed; tracks the performance of a market index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Seeks to outperform an index via active security selection; generally charges higher fees." .
[] a owl:AllDisjointClasses ; owl:members ( fis:IndexFund fis:ActivelyManagedFund ) .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Purchased from or sold to the issuer at NAV at close of trading day." .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
[] a owl:AllDisjointClasses ; owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) .

#################################################################
# FINANCIAL MARKETS
#################################################################

fis:FinancialMarket a owl:Class ; rdfs:comment "A market in which those with a surplus of funds lend to those with a shortage, or in which securities/derivatives are issued or traded." .
fis:PrimaryMarket a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "The market for newly issued securities, in which the issuer receives the sale proceeds directly." .
fis:SecondaryMarket a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "The market for already-issued securities, trading between investors." .
[] a owl:AllDisjointClasses ; owl:members ( fis:PrimaryMarket fis:SecondaryMarket ) .

fis:MoneyMarket a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "Market for short-term funds and instruments with original maturities of one year or less." .
fis:CapitalMarket a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "Market for longer-term instruments, including bonds with maturity over one year and equities." .
[] a owl:AllDisjointClasses ; owl:members ( fis:MoneyMarket fis:CapitalMarket ) .

fis:StockExchange a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .
fis:OverTheCounterMarket a owl:Class ; rdfs:subClassOf fis:FinancialMarket ;
  rdfs:label "OTC market" ;
  rdfs:comment "Buyers and sellers deal directly with each other rather than through a centralized exchange." .
[] a owl:AllDisjointClasses ; owl:members ( fis:StockExchange fis:OverTheCounterMarket ) .

#################################################################
# CASH FLOWS: DIVIDEND VS COUPON
#################################################################

fis:CashFlow a owl:Class ; rdfs:comment "A payment made by or to a holder of a financial instrument." .
fis:Dividend a owl:Class ; rdfs:subClassOf fis:CashFlow ;
  rdfs:comment "A discretionary portion of a company's profit paid to shareholders; not a contractual obligation and not guaranteed, in contrast to a bond coupon." .
fis:CouponPayment a owl:Class ; rdfs:subClassOf fis:CashFlow ;
  rdfs:comment "A contractual, fixed periodic interest payment owed by a bond issuer to the holder." .
fis:PrincipalRepayment a owl:Class ; rdfs:subClassOf fis:CashFlow ;
  rdfs:comment "Repayment of the face/par amount of a debt security, typically at maturity." .
[] a owl:AllDisjointClasses ; owl:members ( fis:Dividend fis:CouponPayment fis:PrincipalRepayment ) .

#################################################################
# IFRS 9 MEASUREMENT TAXONOMY (ORTHOGONAL TO MARKET TAXONOMY)
#################################################################

fis:BusinessModel a owl:Class .
fis:HoldToCollectModel a owl:Class ; rdfs:subClassOf fis:BusinessModel .
fis:HoldToCollectAndSellModel a owl:Class ; rdfs:subClassOf fis:BusinessModel .
fis:OtherBusinessModel a owl:Class ; rdfs:subClassOf fis:BusinessModel .
[] a owl:AllDisjointClasses ; owl:members ( fis:HoldToCollectModel fis:HoldToCollectAndSellModel fis:OtherBusinessModel ) .

fis:CashFlowCharacteristic a owl:Class .
fis:SPPICashFlow a owl:Class ; rdfs:subClassOf fis:CashFlowCharacteristic ;
  rdfs:label "solely payments of principal and interest" .
fis:NonSPPICashFlow a owl:Class ; rdfs:subClassOf fis:CashFlowCharacteristic .
[] a owl:AllDisjointClasses ; owl:members ( fis:SPPICashFlow fis:NonSPPICashFlow ) .

fis:MeasurementCategory a owl:Class .
fis:AmortizedCostMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
fis:FairValueOCIMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ; rdfs:label "FVOCI" .
fis:FairValueProfitOrLossMeasurement a owl:Class ; rdfs:subClassOf fis:MeasurementCategory ; rdfs:label "FVTPL" .
[] a owl:AllDisjointClasses ;
   owl:members ( fis:AmortizedCostMeasurement fis:FairValueOCIMeasurement fis:FairValueProfitOrLossMeasurement ) .

fis:AmortizedCostAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "Measured at amortised cost under IFRS 9 because it is held to collect contractual cash flows that are solely payments of principal and interest." .
fis:AmortizedCostAsset owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
    [ a owl:Restriction ; owl:onProperty fis:hasBusinessModel ; owl:someValuesFrom fis:HoldToCollectModel ]
    [ a owl:Restriction ; owl:onProperty fis:hasCashFlowCharacteristic ; owl:someValuesFrom fis:SPPICashFlow ]
  )
] .
fis:FairValueOCIAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "Measured at fair value through other comprehensive income under IFRS 9." .
fis:FairValueOCIAsset owl:equivalentClass [
  a owl:Class ; owl:intersectionOf ( fis:FinancialAsset
    [ a owl:Restriction ; owl:onProperty fis:hasBusinessModel ; owl:someValuesFrom fis:HoldToCollectAndSellModel ]
    [ a owl:Restriction ; owl:onProperty fis:hasCashFlowCharacteristic ; owl:someValuesFrom fis:SPPICashFlow ]
  )
