fis:CashFlowCharacteristic a owl:Class .

fis:Claim a owl:Class ;
    rdfs:comment "The nature of the holder's claim on the issuer under a security." .

fis:ConvertibleBond a owl:Class ;
    rdfs:label "convertible debenture",
        "convertible note" ;
    rdfs:comment "A bond convertible into the issuer's common stock; typically yields less than comparable non-convertible debt." ;
    rdfs:subClassOf fis:Bond,
        fis:CompoundFinancialInstrument,
        fis:ConvertibleSecurity .

fis:ConvertibleSecurity a owl:Class ;
    rdfs:comment "A bond or preferred stock that the holder may convert, at election, into the ordinary shares of the issuer (or, for exchangeables, another corporation)." ;
    rdfs:subClassOf fis:HybridSecurity ;
    owl:equivalentClass [ a owl:Class ;
            owl:intersectionOf ( fis:HybridSecurity [ a owl:Restriction ;
                        owl:onProperty fis:hasConversionTarget ;
